package com.example.starter.exposure.repo;

import com.example.starter.exposure.domain.ActivityDayConfig;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

/**
 * 活动 UTC 日匀速投放配置数据访问：配置主表 + 24 行小时预算。
 * 加锁方法必须在事务内调用。
 */
@Repository
public class ActivityDayConfigRepository {

    private static final int HOURS_PER_DAY = 24;

    private final JdbcTemplate jdbc;

    public ActivityDayConfigRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按活动与 UTC 日读取配置（无锁）；不存在返回 empty。
     */
    public Optional<ActivityDayConfig> findConfig(String activityId, LocalDate utcDate) {
        return load(activityId, utcDate, false);
    }

    /**
     * 行锁读取配置主行后装配 24 小时预算；不存在返回 empty。必须在事务内调用。
     */
    public Optional<ActivityDayConfig> lockConfig(String activityId, LocalDate utcDate) {
        return load(activityId, utcDate, true);
    }

    /**
     * 插入配置主行与 24 行小时预算；主键冲突由调用方依据唯一约束处理。
     */
    public void insert(ActivityDayConfig config) {
        jdbc.update("INSERT INTO activity_day_config "
                        + "(activity_id, utc_date, daily_total_cap, version, updated_at_utc) "
                        + "VALUES (?, ?, ?, ?, ?)",
                config.activityId(), java.sql.Date.valueOf(config.utcDate()),
                config.dailyTotalCap(), config.version(), config.updatedAtUtc());
        insertBudgets(config);
    }

    /**
     * 版本 CAS 更新：仅当当前版本等于 expectedVersion 时更新主行并重写 24 行预算。
     *
     * @return 是否更新成功（并发修改时只有一个返回 true）
     */
    public boolean update(ActivityDayConfig config, long expectedVersion) {
        int rows = jdbc.update("UPDATE activity_day_config "
                        + "SET daily_total_cap = ?, version = ?, updated_at_utc = ? "
                        + "WHERE activity_id = ? AND utc_date = ? AND version = ?",
                config.dailyTotalCap(), config.version(), config.updatedAtUtc(),
                config.activityId(), java.sql.Date.valueOf(config.utcDate()), expectedVersion);
        if (rows != 1) {
            return false;
        }
        jdbc.update("DELETE FROM activity_hour_budget WHERE activity_id = ? AND utc_date = ?",
                config.activityId(), java.sql.Date.valueOf(config.utcDate()));
        insertBudgets(config);
        return true;
    }

    private Optional<ActivityDayConfig> load(String activityId, LocalDate utcDate, boolean forUpdate) {
        String sql = "SELECT activity_id, utc_date, daily_total_cap, version, updated_at_utc "
                + "FROM activity_day_config WHERE activity_id = ? AND utc_date = ?"
                + (forUpdate ? " FOR UPDATE" : "");
        List<ActivityDayConfig> head = jdbc.query(sql,
                (rs, rowNum) -> new ActivityDayConfig(
                        rs.getString("activity_id"),
                        rs.getDate("utc_date").toLocalDate(),
                        rs.getInt("daily_total_cap"),
                        Collections.emptyList(),
                        rs.getLong("version"),
                        rs.getLong("updated_at_utc")),
                activityId, java.sql.Date.valueOf(utcDate));
        if (head.isEmpty()) {
            return Optional.empty();
        }
        ActivityDayConfig config = head.get(0);
        List<Integer> budgets = new ArrayList<>(Collections.nCopies(HOURS_PER_DAY, 0));
        jdbc.query("SELECT hour_of_day, budget FROM activity_hour_budget "
                        + "WHERE activity_id = ? AND utc_date = ? ORDER BY hour_of_day",
                rs -> {
                    budgets.set(rs.getInt("hour_of_day"), rs.getInt("budget"));
                },
                activityId, java.sql.Date.valueOf(utcDate));
        return Optional.of(new ActivityDayConfig(
                config.activityId(), config.utcDate(), config.dailyTotalCap(),
                Collections.unmodifiableList(budgets), config.version(), config.updatedAtUtc()));
    }

    private void insertBudgets(ActivityDayConfig config) {
        for (int hour = 0; hour < HOURS_PER_DAY; hour++) {
            jdbc.update("INSERT INTO activity_hour_budget (activity_id, utc_date, hour_of_day, budget) "
                            + "VALUES (?, ?, ?, ?)",
                    config.activityId(), java.sql.Date.valueOf(config.utcDate()),
                    hour, config.hourlyBudgets().get(hour));
        }
    }
}

package com.example.starter.exposure.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * 活动小时名额账目数据访问。所有加锁/增减方法必须在事务内调用，
 * 依赖 SELECT ... FOR UPDATE 行锁与 CHECK (used &gt;= 0) 约束保证并发下不超卖、不变负。
 */
@Repository
public class ActivityHourLedgerRepository {

    private final JdbcTemplate jdbc;

    public ActivityHourLedgerRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 确保活动某 UTC 日某小时账目行存在（不存在则以 0 创建）。 */
    public void ensureRow(String activityId, LocalDate utcDate, int hourOfDay) {
        jdbc.update("INSERT INTO activity_hour_ledger (activity_id, utc_date, hour_of_day, used) "
                        + "SELECT ?, ?, ?, 0 WHERE NOT EXISTS ("
                        + "SELECT 1 FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?)",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay,
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
    }

    /** 行锁读取该小时已占用名额；账目行不存在视为 0。 */
    public int lockUsed(String activityId, LocalDate utcDate, int hourOfDay) {
        Integer value = jdbc.query("SELECT used FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ? FOR UPDATE",
                rs -> rs.next() ? rs.getInt(1) : null,
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        return value == null ? 0 : value;
    }

    /**
     * 占用该小时名额（+delta）。调用方须已持行锁并完成容量校验。
     */
    public void addUsed(String activityId, LocalDate utcDate, int hourOfDay, int delta) {
        int rows = jdbc.update("UPDATE activity_hour_ledger SET used = used + ? "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                delta, activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " hour " + hourOfDay);
        }
    }

    /** 释放该小时名额（-1）；CHECK 约束保证不变负。 */
    public void release(String activityId, LocalDate utcDate, int hourOfDay) {
        int rows = jdbc.update("UPDATE activity_hour_ledger SET used = used - 1 "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " hour " + hourOfDay);
        }
    }

    /** 读取活动某 UTC 日各小时已占用名额；无账目行的小时不在返回表中（视为 0）。 */
    public Map<Integer, Integer> usedByHour(String activityId, LocalDate utcDate) {
        Map<Integer, Integer> used = new HashMap<>();
        jdbc.query("SELECT hour_of_day, used FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ?",
                rs -> {
                    used.put(rs.getInt("hour_of_day"), rs.getInt("used"));
                },
                activityId, java.sql.Date.valueOf(utcDate));
        return used;
    }
}

package com.example.starter.exposure.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;

/**
 * 活动日结快照数据访问。快照行一经写入不再更新，
 * 后续配置变更不改写已结算日。
 */
@Repository
public class ActivitySettlementRepository {

    /**
     * 日结快照行视图。
     *
     * @param hourOfDay      小时序号，取值 0..23
     * @param confirmedCount 该小时确认数，单位次
     * @param cancelledCount 该小时取消数，单位次
     * @param expiredCount   该小时过期数，单位次
     * @param settledAtUtc   快照固化时刻（epoch 毫秒，UTC）
     */
    public record SettlementRow(int hourOfDay, int confirmedCount, int cancelledCount,
                                int expiredCount, long settledAtUtc) {
    }

    private static final RowMapper<SettlementRow> MAPPER = (rs, rowNum) -> new SettlementRow(
            rs.getInt("hour_of_day"),
            rs.getInt("confirmed_count"),
            rs.getInt("cancelled_count"),
            rs.getInt("expired_count"),
            rs.getLong("settled_at_utc"));

    private final JdbcTemplate jdbc;

    public ActivitySettlementRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 按小时升序读取活动某 UTC 日的快照行；未固化时返回空或部分行。 */
    public List<SettlementRow> findRows(String activityId, LocalDate utcDate) {
        return jdbc.query("SELECT hour_of_day, confirmed_count, cancelled_count, expired_count, settled_at_utc "
                        + "FROM activity_day_settlement "
                        + "WHERE activity_id = ? AND utc_date = ? ORDER BY hour_of_day",
                MAPPER, activityId, java.sql.Date.valueOf(utcDate));
    }

    /** 固化某小时快照；已存在则跳过（并发固化结果一致，不产生主键冲突）。 */
    public void insertIfAbsent(String activityId, LocalDate utcDate, int hourOfDay,
                               int confirmedCount, int cancelledCount, int expiredCount, long settledAtUtc) {
        jdbc.update("INSERT INTO activity_day_settlement "
                        + "(activity_id, utc_date, hour_of_day, confirmed_count, cancelled_count, "
                        + "expired_count, settled_at_utc) "
                        + "SELECT ?, ?, ?, ?, ?, ?, ? WHERE NOT EXISTS ("
                        + "SELECT 1 FROM activity_day_settlement "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?)",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay,
                confirmedCount, cancelledCount, expiredCount, settledAtUtc,
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
    }
}

