import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 配置/修改活动某 UTC 日匀速投放请求。24 个小时预算必须均为非负整数且合计等于日总确认额度；
 * 修改已存在的配置需携带当前版本号，已开始小时不可下调。
 *
 * @param requestId       写操作全局唯一幂等键
 * @param expectedVersion 期望的当前配置版本；该日尚无配置时必须为 0
 * @param dailyTotalCap   该日总确认额度，单位次，非负
 * @param hourlyBudgets   24 个小时预算（下标即小时 0..23），单位次，非负且合计等于 dailyTotalCap
 */
public record UpsertActivityDayConfigRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotNull @PositiveOrZero Long expectedVersion,
        @NotNull @PositiveOrZero Integer dailyTotalCap,
        @NotNull @Size(min = 24, max = 24) List<@NotNull @PositiveOrZero Integer> hourlyBudgets
) {
}

package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.ActivityDayConfig;

import java.time.LocalDate;
import java.util.List;

/**
 * 活动某 UTC 日匀速投放配置视图。
 *
 * @param activityId     活动编号
 * @param utcDate        配置所属 UTC 日，格式 yyyy-MM-dd
 * @param dailyTotalCap  该日总确认额度，单位次
 * @param hourlyBudgets  24 个小时预算（下标即小时 0..23），单位次
 * @param version        配置版本，每次修改 +1
 * @param updatedAtUtc   最近修改时刻，epoch 毫秒，UTC
 */
public record ActivityDayConfigResponse(
        String activityId,
        LocalDate utcDate,
        int dailyTotalCap,
        List<Integer> hourlyBudgets,
        long version,
        long updatedAtUtc
) {
    public static ActivityDayConfigResponse from(ActivityDayConfig config) {
        return new ActivityDayConfigResponse(
                config.activityId(),
                config.utcDate(),
                config.dailyTotalCap(),
                config.hourlyBudgets(),
                config.version(),
                config.updatedAtUtc());
    }
}

package com.example.starter.exposure.web;

import java.time.LocalDate;
import java.util.List;

/**
 * 活动某 UTC 日逐小时名额诊断视图。
 *
 * @param activityId    活动编号
 * @param utcDate       查询的 UTC 日，格式 yyyy-MM-dd
 * @param configured    该日是否已配置小时预算
 * @param dailyTotalCap 该日总确认额度，单位次；未配置为 null
 * @param version       配置版本；未配置为 null
 * @param usedTotal     该日各小时已占用名额合计，单位次
 * @param hours         24 个小时明细（下标即小时 0..23）
 * @param queriedAtUtc  查询时刻，epoch 毫秒，UTC
 */
public record ActivityDayQuotaResponse(
        String activityId,
        LocalDate utcDate,
        boolean configured,
        Integer dailyTotalCap,
        Long version,
        int usedTotal,
        List<ActivityHourQuota> hours,
        long queriedAtUtc
) {
    /**
     * 单个小时的名额明细。
     *
     * @param hourOfDay    小时序号，取值 0..23
     * @param hourStartUtc 小时起点，epoch 毫秒，UTC，区间左闭右开
     * @param budget       该小时预算，单位次；未配置为 null
     * @param used         该小时已占用名额（RESERVED 与 CONFIRMED 合计），单位次
     * @param remaining    该小时剩余名额，单位次；未配置为 null
     */
    public record ActivityHourQuota(
            int hourOfDay,
            long hourStartUtc,
            Integer budget,
            int used,
            Integer remaining
    ) {
    }
}

package com.example.starter.exposure.web;

import java.time.LocalDate;
import java.util.List;

/**
 * 活动某 UTC 日结视图。UTC 日结束后首次查询固化快照，后续配置变更不改写已结算日；
 * 当日或未到的日返回实时统计。
 *
 * @param activityId   活动编号
 * @param utcDate      查询的 UTC 日，格式 yyyy-MM-dd
 * @param settled      是否已固化（该 UTC 日已结束）
 * @param settledAtUtc 快照固化时刻，epoch 毫秒，UTC；未固化为 null
 * @param hours        24 个小时结算明细（下标即小时 0..23）
 */
public record ActivityDaySettlementResponse(
        String activityId,
        LocalDate utcDate,
        boolean settled,
        Long settledAtUtc,
        List<ActivityHourSettlement> hours
) {
    /**
     * 单个小时的结算明细。
     *
     * @param hourOfDay      小时序号，取值 0..23
     * @param confirmedCount 该小时确认数，单位次
     * @param cancelledCount 该小时取消数，单位次
     * @param expiredCount   该小时过期数，单位次
     * @param reservedCount  该小时仍为 RESERVED 的数量（仅实时统计可能非 0），单位次
     */
    public record ActivityHourSettlement(
            int hourOfDay,
            int confirmedCount,
            int cancelledCount,
            int expiredCount,
            int reservedCount
    ) {
    }
}

